"-- RLS Migration for CRM tables\n-- Maps Prisma-based lib/authz/scopes logic to PostgreSQL Row Level Security\n\n-- 1. Helper function for role\nCREATE OR REPLACE FUNCTION public.get_auth_role()\nRETURNS text\nLANGUAGE sql\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT role::text FROM public.\"Users\" WHERE id = auth.uid()::uuid;\n$$;\n\n-- 2. Enable RLS and create policies for core CRM entities\n\n-- crm_Accounts\nALTER TABLE public.\"crm_Accounts\" ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \"crm_Accounts_access\" ON public.\"crm_Accounts\"\nFOR ALL USING (\n  public.get_auth_role() IN ('admin', 'manager', 'ADMIN', 'MANAGER')\n  OR \"assigned_to\" = auth.uid()::uuid\n  OR \"createdBy\" = auth.uid()::uuid\n  OR EXISTS (SELECT 1 FROM public.\"AccountWatchers\" WHERE \"account_id\" = public.\"crm_Accounts\".id AND \"user_id\" = auth.uid()::uuid)\n);\n\n-- crm_Contacts\nALTER TABLE public.\"crm_Contacts\" ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \"crm_Contacts_access\" ON public.\"crm_Contacts\"\nFOR ALL USING (\n  public.get_auth_role() IN ('admin', 'manager', 'ADMIN', 'MANAGER')\n  OR \"assigned_to\" = auth.uid()::uuid\n  OR \"createdBy\" = auth.uid()::uuid\n  OR \"accountsIDs\" IN (\n    SELECT id FROM public.\"crm_Accounts\" WHERE \n      public.get_auth_role() IN ('admin', 'manager', 'ADMIN', 'MANAGER')\n      OR \"assigned_to\" = auth.uid()::uuid\n      OR \"createdBy\" = auth.uid()::uuid\n      OR EXISTS (SELECT 1 FROM public.\"AccountWatchers\" WHERE \"account_id\" = id AND \"user_id\" = auth.uid()::uuid)\n  )\n);\n\n-- crm_Leads\nALTER TABLE public.\"crm_Leads\" ENABLE ROW LEVEL SECURITY;\nCREATE POLICY \"crm_Leads_access\" ON public.\"crm_Leads\"\nFOR ALL USING (\n  public.get_auth_role() IN ('admin', 'manager', 'ADMIN', 'MANAGER')\n  OR \"assigned_to\" = auth.uid()::uuid\n  OR \"createdBy\" = auth.uid()::uuid\n  OR \"accountsIDs\" IN (\n    SELECT id FROM public.\"crm_Accounts\" WHERE \n      public.get_auth_role() IN ('admin', 'manager', 'AD